async function offlineRaw(key, value) {
  const db = await offlineDb();
  return new Promise((resolve, reject) => {
    let result, tx;
    const fail = (error) => { db.close(); reject(error || new Error("Local storage transaction failed. Keep this page open.")); };
    try {
      tx = db.transaction("records", value === undefined ? "readonly" : "readwrite");
      tx.oncomplete = () => { db.close(); resolve(result); };
      tx.onabort = () => fail(tx.error);
      tx.onerror = () => fail(tx.error);
      const request = value === undefined ? tx.objectStore("records").get(key) : tx.objectStore("records").put(value, key);
      request.onsuccess = () => { result = request.result; };
      request.onerror = () => fail(request.error);
    } catch (error) { fail(error); }
  });
}

