async function offlineCryptoKey() {
  const existing = await offlineRaw("device-key");
  if (existing) return existing;
  const candidate = await crypto.subtle.generateKey({ name:"AES-GCM", length:256 }, false, ["encrypt", "decrypt"]);
  const db = await offlineDb();
  return new Promise((resolve, reject) => {
    let key, tx;
    const fail = (error) => { db.close(); reject(error || new Error("Local encryption key could not be saved.")); };
    try {
      tx = db.transaction("records", "readwrite");
      tx.oncomplete = () => { db.close(); resolve(key); };
      tx.onabort = () => fail(tx.error);
      tx.onerror = () => fail(tx.error);
      const store = tx.objectStore("records"), read = store.get("device-key");
      read.onerror = () => fail(read.error);
      read.onsuccess = () => {
        key = read.result || candidate;
        if (!read.result) { const write = store.put(key, "device-key"); write.onerror = () => fail(write.error); }
      };
    } catch (error) { fail(error); }
  });
}

patches.offlineLoad:
async function offlineLoad(key) {
  const record = await offlineRaw(key);
  if (record === undefined) return null;
  if (!record || !record.iv || !record.encrypted) throw new Error("Saved local data could not be read. Keep this browser open; do not clear site data.");
  const keyValue = await offlineRaw("device-key");
  if (!keyValue) throw new Error("The encryption key for existing local data is missing. Do not clear or overwrite site data.");
  const bytes = await crypto.subtle.decrypt({ name:"AES-GCM", iv:record.iv }, keyValue, record.encrypted);
  return JSON.parse(new TextDecoder().decode(bytes));
}

