async function loadHeldSales() {
  if (!selectedPosBranchId) return false;
  const branchId = selectedPosBranchId;
  heldLoadError = "";
  try {
    const local = appMode === "staff" ? await heldStorageRows("held-sales-local:" + branchId) : [];
    let remote;
    try {
      const result = await api("/api/held-sales?branchId=" + encodeURIComponent(branchId));
      remote = result.heldSales;
      if (appMode === "staff") {
        try { await offlineSave("held-sales:" + branchId, remote); }
        catch { heldLoadError = "Cloud payments loaded, but a local backup could not be saved. Keep this page open."; }
      }
    } catch (error) {
      heldLoadError = error.message;
      if (appMode !== "staff" || (!offlineNetworkError(error) && !error.authRequired && !error.cloudUnconfirmed)) throw error;
      const cached = await offlineLoad("held-sales:" + branchId);
      if (cached !== null && !Array.isArray(cached)) throw new Error("Saved cloud-held-payment backup is unreadable. Existing records have not been overwritten.");
      remote = cached === null ? heldSales.filter(item => !item.local && item.branch_id === branchId) : cached;
    }
    const pending = appMode === "staff" ? await offlineQueue() : [];
    const pendingSaleIds = new Set(pending.map(item => item.payload?.heldSaleId).filter(Boolean));
    if (selectedPosBranchId !== branchId) return false;
    heldSales = [...local, ...remote.filter(item => !local.some(pending => pending.id === item.id))].filter(item => !pendingSaleIds.has(item.id));
    renderHeldSales();
    if (heldLoadError) message.textContent = "Held payments: " + heldLoadError;
    return !heldLoadError;
  } catch (error) {
    heldLoadError = error.message;
    message.textContent = "Held payments could not be refreshed. Existing records were retained. " + error.message;
    return false;
  }
}

