async function syncLocalHolds() {
  if (heldSalesSyncing || !navigator.onLine || !selectedPosBranchId) return;
  heldSalesSyncing = true;
  const branchId = selectedPosBranchId;
  let changed = false;
  try {
    await heldStorageLock(branchId, async () => {
      const key = "held-sales-local:" + branchId;
      const local = await heldStorageRows(key);
      for (const hold of local.slice()) {
        const form = document.querySelector("#saleForm");
        if ([form?.dataset.localHeldSaleId, form?.dataset.heldSaleId, form?.dataset.holdAttemptId].includes(hold.id)) continue;
        if (selectedPosBranchId !== branchId) break;
        try { await api("/api/held-sales", { method:"POST", body:JSON.stringify(hold.payload) }); }
        catch (error) {
          hold.syncError = error.authRequired ? "Sign-in required; saved only on this device." : "Cloud save not confirmed. " + error.message;
          await offlineSave(key, local);
          changed = true;
          break;
        }
        local.splice(local.findIndex(item => item.id === hold.id), 1);
        await offlineSave(key, local);
        changed = true;
      }
    });
    if (changed && selectedPosBranchId === branchId) { await loadHeldSales(); await updateOfflineStatus(); }
  } catch (error) {
    message.textContent = "Held-payment sync stopped; saved records were retained. " + error.message;
  } finally { heldSalesSyncing = false; }
}

patches.removeLocalHeldSale:
async function removeLocalHeldSale(id) {
  if (!id || appMode !== "staff") return;
  const branchId = selectedPosBranchId;
  await heldStorageLock(branchId, async () => {
    const key = "held-sales-local:" + branchId;
    const local = await heldStorageRows(key);
    if (local.some(item => item.id === id)) await offlineSave(key, local.filter(item => item.id !== id));
  });
}

